using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using CatGunner.Runtime;
public static class InstallModeViewport {
 public static object Main(){if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets"||Application.isPlaying)throw new Exception("Correct EditMode required");var c=UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);var roots=new Transform[]{c.SpeedRun.Start_UI.transform,c.MineMode.mineStart_ui.transform,c.BossMode.Start_UI.transform,c.MonsterMode.monster_start_ui.transform,c.RaidMode.raidStart_ui.transform};
 foreach(var root in roots){var fit=root.GetComponent<PenguinModeViewport>();if(fit!=null)continue;fit=Undo.AddComponent<PenguinModeViewport>(root.gameObject);fit.Cards=root.Cast<Transform>().Where(t=>t.name!="Background").Select(t=>{var rect=(RectTransform)t;if(rect.anchorMin!=Vector2.one*.5f||rect.anchorMax!=Vector2.one*.5f)throw new Exception("Non-centred mode card: "+t.name);return new PenguinModeViewport.Card{Rect=rect,Position=rect.anchoredPosition,Scale=rect.localScale};}).ToArray();EditorUtility.SetDirty(fit);if(PrefabUtility.IsPartOfPrefabInstance(fit))PrefabUtility.RecordPrefabInstancePropertyModifications(fit);}
 var scene=c.gameObject.scene;EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");return new{roots=roots.Length,saved=true};}
}
